using Microsoft.Testing.Platform.Builder;
using Microsoft.Testing.Platform.Capabilities.TestFramework;
using Microsoft.Testing.Platform.Helpers;
using Microsoft.Testing.Platform.Services;

namespace Cratis.Specifications.Runner;

/// <summary>
/// Registers the Cratis specification runner with Microsoft.Testing.Platform. Called from the entry point generated by
/// Microsoft.Testing.Platform.MSBuild, through the TestingPlatformBuilderHook item added by the package.
/// </summary>
[System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
public static class TestingPlatformBuilderHook
{
    /// <summary>
    /// Adds the Cratis specification runner to the test application.
    /// </summary>
    /// <param name="builder">The test application builder.</param>
    /// <param name="arguments">The command line arguments.</param>
    public static void AddExtensions(ITestApplicationBuilder builder, string[] arguments)
    {
        _ = arguments;
        builder.AddCratisSpecifications();
    }

    /// <summary>
    /// Adds the Cratis specification runner to the test application.
    /// </summary>
    /// <param name="builder">The test application builder.</param>
    public static void AddCratisSpecifications(this ITestApplicationBuilder builder)
    {
        var trx = new TrxCapability();
        builder.AddTreeNodeFilterService(new SpecificationCommandLineOptions());
        builder.CommandLine.AddProvider(static () => new SpecificationCommandLineOptions());
        builder.RegisterTestFramework(
            _ => new TestFrameworkCapabilities(trx),
            (_, services) =>
            {
                var commandLine = services.GetCommandLineOptions();
                return new SpecificationFramework(SpecificationCommandLineOptions.Read(commandLine), trx, commandLine.IsOptionSet("server"), new OutputDeviceSpecificationOutput(services.GetOutputDevice()));
            });
    }
}
